const visible=computed(()=>props.options.filter(o=>(!category.value||o.category===category.value)&&o.label.toLowerCase().includes(query.value.trim().toLowerCase())))
const optionId=value=>`${props.id}-option-${encodeURIComponent(value||'all')}`
