function place(){if(!open.value||!trigger.value)return;const r=trigger.value.getBoundingClientRect(),v=window.visualViewport,left=v?.offsetLeft||0,top=v?.offsetTop||0,w=v?.width||innerWidth,h=v?.height||innerHeight,width=Math.min(props.variant==='market'?352:props.variant==='field'?r.width:props.searchLabel?224:144,w-16),desired=props.variant==='market'?374:props.searchLabel?279:Math.min(280,props.options.length*32+8),below=top+h-r.bottom-36,above=r.top-top-8,up=below<desired&&above>below,height=Math.min(desired,Math.max(80,up?above:below));geometry.value={left:Math.max(left+8,Math.min(r.left,left+w-width-8))+'px',top:(up?r.top-height-4:r.bottom+4)+'px',width:width+'px',maxHeight:height+'px'}}
function listen(add){const fn=add?'addEventListener':'removeEventListener';document[fn]('pointerdown',outside,true);document[fn]('focusin',focusChanged);window[fn]('resize',place);window[fn]('scroll',place,true);window.visualViewport?.[fn]('resize',place);window.visualViewport?.[fn]('scroll',place)}
